struct Vertex { var position: SIMD3<Float> }

class MetalTriangleRenderer: NSObject, MTKViewDelegate {
    let pipeline: MetalPipeline
    let vertexBuffer: MTLBuffer

    init(view: MTKView) {
        self.pipeline = MetalPipeline()
        let vertices = [
            Vertex(position: [-0.5, -0.5, 0]),
            Vertex(position: [ 0.5, -0.5, 0]),
            Vertex(position: [ 0.0,  0.5, 0])
        ]
        self.vertexBuffer = pipeline.device.makeBuffer(bytes: vertices, length: MemoryLayout<Vertex>.stride * 3)
        super.init()
        view.delegate = self
    }

    func draw(in view: MTKView) {
        guard let drawable = view.currentDrawable,
              let descriptor = view.currentRenderPassDescriptor else { return }

        let commandBuffer = pipeline.commandQueue.makeCommandBuffer()!
        let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: descriptor)!

        encoder.setRenderPipelineState(pipeline.pipelineState)
        encoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
        encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)

        encoder.endEncoding()
        commandBuffer.present(drawable)
        commandBuffer.commit()
    }
}

