fragment float4 fragment_main(VertexOut in [[stage_in]], texture2d<float> tex [[texture(0)]]) {
    float2 uv = in.uv;
    float3 col = float3(0);
    float kernel[9] = {0.05, 0.09, 0.12, 0.15, 0.16, 0.15, 0.12, 0.09, 0.05};

    for (int i = -4; i <= 4; i++) {
        col += tex.sample(sampler(address::clamp_to_edge), uv + float2(i) * 0.002).rgb * kernel[i+4];
    }
    return float4(col, 1);
}

